"""Original fixed-step offline models; never execute Helm or cluster requests."""
def step(title,explanation,actor,focus,active,states,field):
    name,before,after,why=field
    return dict(title=title,explanation=explanation,actor=actor,focus=focus,active=active,states=states,
      fields=[dict(name=name,before=before,after=after,why=why)],bands=[dict(label=name,value=after,detail=why)])
def diagram(identifier,chapter,title,intro,assumptions,nodes,edges,steps):
    return dict(id=identifier,volume='helm',chapter=chapter,anchor=chapter,title=title,intro=intro,
      assumptions=assumptions,insert_before='<h2>Первичные источники и версия</h2>',
      nodes=[dict(id=i,label=l,sub=s) for i,l,s in nodes],
      edges=[dict(id=i,**{'from':a,'to':b},label=l) for i,a,b,l in edges],steps=steps)
